transforms.code:

assetInfo = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.asset.getAssets({'assetPath': value or 'No asset selected'}),0)
attributes = system.kanoa.utilities.convertDatasetToDict(system.kanoa.asset.getAssetAttributes({'assetId': assetInfo['assetId']}), 'assetAttrName', None)

return {'attributes': attributes, 'assetInfo' : assetInfo, 'tagInfo': None}


assetId = value['asset']['assetInfo']['assetId']
if assetId is None: return []

rateInfo = self.custom.rateInfo

paramsDict = {'assetId': assetId, 'startDate': value['filter']['dateRange']['startDate'], 'endDate': (value['filter']['dateRange']['endDate'] or system.date.now())}
data = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.event.getCounterEventTotals(paramsDict))

modeItemId = None
paramsDict['modeId'] = system.kanoa.utilities.getFieldValue('modeId', system.kanoa.asset.getAssetModes({'assetId': assetId, 'modeName': 'Production'}))
modeEvents = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.event.getAssetProductionEvents(paramsDict))
for modeEvent in modeEvents:
	if modeEvent['itemId']:
		modeItemId = modeEvent['itemId']
		break

values = []
failedUnits = {}
for row in data:
	row = dict(row)
	if row['value'] == 0: continue
	row['itemUnitName'] = 'units'		
	assetPath = row['assetPath']
	assetName = row['assetName']
	itemPath =  row['itemPath']
	itemId = row['itemId'] or modeItemId
	if rateInfo.has_key(itemId):
		try:
			taktTime = 60.0 / rateInfo['standardRate'] if rateInfo['itemPeriodName'] == 'Hour' else rateInfo['standardRate'] 
		except:
			pass

		if row['counterName'] == 'infeed':	row['itemUnitName'] = rateInfo[itemId]['infeedUnits']
		elif row['counterName'] == 'outfeed':	row['itemUnitName'] = rateInfo[itemId]['outfeedUnits']
		elif row['counterName'] == 'waste':	row['itemUnitName'] = rateInfo[itemId]['wasteUnits']

	failedName = "%s - %s"%(assetName, itemPath)
	if row['counterName'] != 'waste': values.append(row)
	elif not failedUnits.has_key(failedName): failedUnits[failedName] = row
	else: failedUnits[failedName]['value'] += row['value']		

for k,v in failedUnits.items(): values.append(v)

return sorted(values, key=lambda x: x['itemPath'])

page = 'designer' if '/' in value['page'] else value['page']
filterInfo = dict(system.kanoa.dashboard.getWidgetFilters(value['page'], value['viewParams'], value['sessionCustomProps'], self.session.props.device.timezone.id))

dateRange = dict(filterInfo.get('dateRange') or {})

if filterInfo.has_key('options') and not filterInfo['options']['useFilterDate']:
	if self.custom.tagInfo is not None: dateRange['startDate'] = system.date.fromMillis(self.custom.tagInfo.startDate)
	dateRange['endDate'] = None
elif 'current' in filterInfo['dateRange']['selectedRange'].lower():
	dateRange['endDate'] = None

filterInfo['dateRange'] = dateRange

return filterInfo

onChange.script:
#We'll refresh the counts if the tag values change and date range is set to 'current...

filters = self.custom.filter
if filters is None: return
if not filters.has_key('dateRange'): return

try:
	if 'current' in filters.dateRange.selectedRange.lower(): self.refreshBinding("custom.countInfo")
except:
	pass

return

transforms.code:
countInfo = value['countInfo']
displayInfo = value['params']['display']

instances = []
for item in countInfo:
	rowColor = '--kcRed-60' if item['counterName'] == 'waste' else ''

	itemAsset = {"value": item['assetName'], "style": {"color": rowColor, 'textAlign': 'center'}}

	itemName = {"style": {"color": rowColor}}
	if item['workOrderName'] and displayInfo['showOrder']: itemName['value'] = "%s | %s"%(item['workOrderName'], item['itemName'] or '')
	else: itemName['value'] = "%s"%(item['itemName'] or '')

	if item['itemStatePath']:
		itemStateName = "%s %s"%(item['counterName'].title(), item['itemStateName'])
	else: itemStateName = item['counterName'].title()

	itemState = {"value": itemStateName, "style": {"color": rowColor}}

	units = item['itemUnitName'] or ''
	itemValue = "{:,.0f} {}".format(item['value'], units)

	itemValue = {"value": itemValue, "style": {"color": rowColor, 'textAlign': 'center'}}
	instances.append({"assetId": item['assetId'], "assetPath": item['assetPath'], "assetName": itemAsset, "itemName": itemName, "itemState": itemState, "itemValue": itemValue})

return instances


if len(value) == 0: return ''
count = system.math.sum([item['value'] for item in value if item['value'] is not None])
return str(int(count))
